// nimbus-forecast-card.js
//
// nimbus issue #1529: the Forecaster's charts, auto-detected.
//
// This is the reference household's own Forecaster view, the two
// apexcharts-card charts "Nimbus Power Signals" and "Nimbus Load
// Forecasts", made portable. On that install they are generated by a
// Python script (116KAT-HA-AI scripts/lovelace_build_merged_forecast_chart.py)
// against its own entity ids. Here the same configuration is built in the
// browser from whatever Nimbus entities the install actually has, so any
// household gets the same charts with no entity list to maintain. Rendering
// is delegated to apexcharts-card (HACS), exactly as on the reference install.
//
// What is discovered, never listed:
//   * every Nimbus Load forecast            -> Load Forecasts chart
//   * every Nimbus Power Signal forecast    -> Power Signals chart
//       battery / grid / solar by signal_role, else by entity_id keyword,
//       the same rule as the generator script
//   * the Solver's configured load forecast -> the white Whole House line
//   * temperature / humidity Power Signals  -> the weather overlay
//   * sensor.nimbus_solver_battery_forecast -> the Solver's proposed series
//   * each forecast's own `source_sensor`   -> its measured (history) line,
//       scaled W -> kW where the source reports W
//
// Colours for circuits use the generator script's own hash of the forecast
// entity_id, so an existing household's circuits keep their colours.
//
// config (all optional):
//   chart: "both" (default) | "signals" | "loads"

const NIMBUS_FC_HIST_SUFFIX = " (history)";

// Port of _hash_color_for() in the generator script: Python's
// colorsys.hls_to_rgb(hue, 0.55, 0.55) on a 31-multiplier string hash.
// Must stay equivalent so colours do not change for anyone moving from
// the script-built chart to this card.
function nimbusFcHashColor(entityId) {
  let h = 0;
  for (let i = 0; i < entityId.length; i++) {
    h = (Math.imul(h, 31) + entityId.charCodeAt(i)) >>> 0;
  }
  const hue = (h % 360) / 360.0;
  const l = 0.55;
  const s = 0.55;
  const m2 = l <= 0.5 ? l * (1 + s) : l + s - l * s;
  const m1 = 2 * l - m2;
  const v = (hh) => {
    hh = ((hh % 1) + 1) % 1;
    if (hh < 1 / 6) return m1 + (m2 - m1) * hh * 6;
    if (hh < 0.5) return m2;
    if (hh < 2 / 3) return m1 + (m2 - m1) * (2 / 3 - hh) * 6;
    return m1;
  };
  const toHex = (x) => Math.floor(x * 255).toString(16).toUpperCase().padStart(2, "0");
  return "#" + toHex(v(hue + 1 / 3)) + toHex(v(hue)) + toHex(v(hue - 1 / 3));
}

const NIMBUS_FC_GEN = {
  value: "return entity.attributes.forecast.map(p => [new Date(p.time).getTime(), p.value]);",
  lower: "return entity.attributes.forecast.map(p => [new Date(p.time).getTime(), p.lower]);",
  upper: "return entity.attributes.forecast.map(p => [new Date(p.time).getTime(), p.upper]);",
};

class NimbusForecastCard extends HTMLElement {
  static powerScaleToKw(unit) {
    // nimbus #1570: the same table as power_units.py (POWER_TO_KW);
    // tests/test_1570_power_units.py checks every card against it.
    const NIMBUS_POWER_TO_KW = {"mw": 1e3, "w": 1e-3, "kw": 1.0, "gw": 1e6, "tw": 1e9, "btu/h": 0.00029307107};
    const NIMBUS_POWER_EXACT = {"mW": 1e-6, "MW": 1e3};
    if (typeof unit !== 'string') return 1;
    const u = unit.trim();
    if (Object.prototype.hasOwnProperty.call(NIMBUS_POWER_EXACT, u)) return NIMBUS_POWER_EXACT[u];
    const k = u.toLowerCase();
    return Object.prototype.hasOwnProperty.call(NIMBUS_POWER_TO_KW, k) ? NIMBUS_POWER_TO_KW[k] : 1;
  }

  static getStubConfig() {
    return {};
  }

  setConfig(config) {
    this._config = config || {};
    this._which = ["signals", "loads"].includes(this._config.chart) ? this._config.chart : "both";
    this._signature = null;
    this._charts = [];
    if (!this.shadowRoot) this.attachShadow({ mode: "open" });
  }

  getCardSize() {
    return this._which === "both" ? 20 : 12;
  }

  // Sections views size a card from this. Without it Home Assistant gives a
  // card a small default tile, which squeezes these wide charts into a
  // narrow column. Full width, height from the content.
  getGridOptions() {
    return { columns: "full", rows: "auto", min_columns: 6 };
  }

  set hass(hass) {
    this._hass = hass;
    if (!customElements.get("apexcharts-card")) {
      this._renderMissing();
      if (!this._waiting) {
        this._waiting = true;
        customElements.whenDefined("apexcharts-card").then(() => {
          this._waiting = false;
          this._signature = null;
          if (this._hass) this.hass = this._hass;
        });
      }
      return;
    }
    const found = this._discover();
    // Rebuild only when the set of entities changes. Every other hass
    // update is passed through to the charts, which redraw themselves.
    const sig = JSON.stringify([
      found.signals.map((s) => s.entity_id),
      found.loads.map((s) => s.entity_id),
      found.house && found.house.entity_id,
      found.weather.map((s) => s.entity_id),
      !!found.solver,
    ]);
    if (sig !== this._signature) {
      this._signature = sig;
      this._build(found);
    }
    for (const c of this._charts) c.hass = hass;
  }

  _discover() {
    const st = this._hass.states;
    const cfg = st["sensor.nimbus_solver_config"];
    const houseId = cfg && cfg.attributes.solver_load_forecast_sensor;
    const out = { signals: [], loads: [], weather: [], house: null, solver: null };
    for (const [id, s] of Object.entries(st)) {
      if (!id.startsWith("sensor.nimbus_") || !id.endsWith("_forecast")) continue;
      if (id.startsWith("sensor.nimbus_solver_")) continue;
      const a = s.attributes || {};
      if (!Array.isArray(a.forecast)) continue;
      if (houseId && id === houseId) {
        out.house = s;
        continue;
      }
      if (a.subentry_type === "load") out.loads.push(s);
      else if (a.subentry_type === "power_signal") {
        if (a.signal_role === "temperature" || a.signal_role === "humidity") out.weather.push(s);
        else out.signals.push(s);
      }
    }
    const byId = (a, b) => a.entity_id.localeCompare(b.entity_id);
    out.signals.sort(byId);
    out.loads.sort(byId);
    out.weather.sort(byId);
    const solver = st["sensor.nimbus_solver_battery_forecast"];
    if (solver && Array.isArray(solver.attributes.forecast)) out.solver = solver;
    return out;
  }

  // Battery / Grid / Solar, the generator script's own rule: an explicit
  // signal_role wins, otherwise the entity_id keyword.
  _category(s) {
    const role = s.attributes.signal_role;
    if (role === "battery" || role === "grid" || role === "solar") return role;
    const eid = s.entity_id.toLowerCase();
    if (eid.includes("battery")) return "battery";
    if (eid.includes("meter") || eid.includes("grid")) return "grid";
    return "solar";
  }

  _shortName(s) {
    let n = s.attributes.friendly_name || s.entity_id;
    for (const suf of [" Power Forecast", " Forecast", " Power"]) {
      if (n.endsWith(suf)) {
        n = n.slice(0, -suf.length);
        break;
      }
    }
    return n.trim();
  }

  // The measured line behind a forecast, as its own series. A W source is
  // scaled to kW so it sits on the same axis as the forecast.
  _history(s, name, color, yaxis, width) {
    const src = s.attributes.source_sensor;
    if (!src || !this._hass.states[src]) return null;
    const unit = (this._hass.states[src].attributes.unit_of_measurement || "").toLowerCase();
    const fu = (s.attributes.unit_of_measurement || "").toLowerCase();
    const series = {
      entity: src,
      name: name + NIMBUS_FC_HIST_SUFFIX,
      extend_to: false,
      color,
      stroke_width: width,
      yaxis_id: yaxis,
      show: { in_header: false, in_legend: false },
    };
    // nimbus #1570: any power unit, not only W behind a kW forecast.
    const k = NimbusForecastCard.powerScaleToKw(unit) / NimbusForecastCard.powerScaleToKw(fu);
    if (k !== 1) series.transform = "return x * " + k + ";";
    return series;
  }

  _absMax(states, fields) {
    let m = 0;
    for (const s of states) {
      for (const p of s.attributes.forecast || []) {
        for (const k of fields) {
          const v = Math.abs(parseFloat(p[k]));
          if (Number.isFinite(v) && v > m) m = v;
        }
      }
    }
    return m;
  }

  _nice(v, floor) {
    const x = Math.max(v * 1.1, floor);
    const step = x > 50 ? 10 : 5;
    return Math.ceil(x / step) * step;
  }

  _base(title, height) {
    return {
      type: "custom:apexcharts-card",
      header: { title, show: true },
      graph_span: "54h",
      span: { offset: "+48h" },
      now: { show: true, label: "now", color: "#E91E63" },
      apex_config: {
        chart: { height },
        legend: { show: true, position: "bottom" },
        annotations: {
          yaxis: [{ y: 0, borderColor: "#FFFFFF", strokeDashArray: 0, borderWidth: 1.5, opacity: 0.5 }],
        },
      },
    };
  }

  _signalsConfig(f) {
    const styles = {
      battery: { label: "Battery", color: "#8BC34A", extra: { type: "area", opacity: 0.2, stroke_width: 2 }, hist: 1 },
      grid: { label: "Grid", color: "#64B5F6", extra: { type: "area", opacity: 0.2, stroke_width: 2 }, hist: 2 },
      solar: { label: "Solar", color: "#FF9800", extra: { stroke_dash: 6, stroke_width: 3 }, hist: 1 },
    };
    const counts = {};
    for (const s of f.signals) counts[this._category(s)] = (counts[this._category(s)] || 0) + 1;
    const pmax = this._nice(
      Math.max(
        this._absMax(f.signals, ["value", "lower", "upper"]),
        f.solver ? this._absMax([f.solver], ["battery_kw", "grid_import_kw", "grid_export_kw"]) : 0
      ),
      5
    );
    const series = [];
    for (const s of f.signals) {
      const cat = this._category(s);
      const st = styles[cat];
      const name = "Nimbus " + st.label + (counts[cat] > 1 ? " " + this._shortName(s) : "");
      const h = this._history(s, name, st.color, "power", st.hist);
      if (h) series.push(h);
      series.push({
        entity: s.entity_id, name, extend_to: false, data_generator: NIMBUS_FC_GEN.value,
        yaxis_id: "power", show: { in_header: true }, color: st.color, ...st.extra,
      });
      for (const b of ["lower", "upper"]) {
        series.push({
          entity: s.entity_id, name: name + " (" + b + " bound)", extend_to: false,
          data_generator: NIMBUS_FC_GEN[b], color: st.color, opacity: 0.85, stroke_width: 2, stroke_dash: 4,
          yaxis_id: "power", show: { in_header: false, in_legend: true },
        });
      }
    }
    // Humidity (%) is drawn on the kW axis, scaled so 100 % sits just
    // inside the top of the axis -- the reference chart's own approach.
    const humScale = Math.round(((pmax * 0.9) / 100) * 100) / 100;
    for (const s of f.weather) {
      const isHum = s.attributes.signal_role === "humidity";
      const name = isHum ? "Humidity" : "Temp";
      const color = isHum ? "#26C6DA" : "red";
      const yax = isHum ? "power" : "temp";
      const src = s.attributes.source_sensor;
      if (src && this._hass.states[src]) {
        const hs = {
          entity: src, name, extend_to: false, color, stroke_width: 1.5, yaxis_id: yax,
          show: { in_header: true, in_legend: true, legend_value: true },
        };
        if (isHum) hs.transform = "return x * " + humScale + ";";
        series.push(hs);
      }
      series.push({
        entity: s.entity_id, name: name + " (forecast)", extend_to: false,
        data_generator: isHum
          ? "return entity.attributes.forecast.map(p => [new Date(p.time).getTime(), p.value * " + humScale + "]);"
          : NIMBUS_FC_GEN.value,
        color, stroke_width: 1.5, stroke_dash: 3, yaxis_id: yax, show: { in_header: true, in_legend: true },
      });
    }
    if (f.solver) {
      const g = (field, neg) =>
        "return entity.attributes.forecast.map(p => [new Date(p.time).getTime(), " +
        (neg ? "-" : "") + "p." + field + "]);";
      series.push(
        {
          entity: f.solver.entity_id, name: "Solver Battery (proposed)", extend_to: false,
          data_generator: g("battery_kw"), yaxis_id: "power", color: "#AB47BC", type: "area", opacity: 0.2,
          stroke_width: 2.5, stroke_dash: 2, show: { in_header: true, in_legend: true },
        },
        {
          entity: f.solver.entity_id, name: "Solver Grid import (proposed)", extend_to: false,
          data_generator: g("grid_import_kw"), yaxis_id: "power", color: "#9575CD", stroke_width: 1.5,
          stroke_dash: 2, show: { in_header: false, in_legend: true },
        },
        {
          entity: f.solver.entity_id, name: "Solver Grid export (proposed)", extend_to: false,
          data_generator: g("grid_export_kw", true), yaxis_id: "power", color: "#4DB6AC", stroke_width: 1.5,
          stroke_dash: 2, show: { in_header: false, in_legend: true },
        },
        {
          entity: f.solver.entity_id, name: "Solver SoC % (proposed)", extend_to: false,
          data_generator: g("soc_pct"), yaxis_id: "soc", color: "#C2185B", stroke_width: 4, stroke_dash: 8,
          // The plan sensor's own unit is kW; this series is a percentage.
          unit: "%", show: { in_header: true, in_legend: true },
        }
      );
    }
    const cfg = this._base("Nimbus Power Signals", 750);
    cfg.yaxis = [
      { id: "power", min: -pmax, max: pmax, decimals: 0, apex_config: { tickAmount: 16, title: { text: "kW" } } },
      { id: "temp", show: false, min: -pmax, max: pmax },
      { id: "humidity", show: true, opposite: false, min: 100, max: 0, decimals: 0, apex_config: { title: { text: "%" } } },
      { id: "load", show: false, min: -pmax, max: pmax },
      { id: "soc", show: true, opposite: true, min: -100, max: 100, apex_config: { title: { text: "SoC %" } } },
    ];
    cfg.series = series;
    return cfg;
  }

  _loadsConfig(f) {
    const all = f.house ? f.loads.concat([f.house]) : f.loads;
    const lmax = this._nice(this._absMax(all, ["value"]), 5);
    const series = [];
    for (const s of f.loads) {
      const eid = s.entity_id.toLowerCase();
      // Pool and hot water are the schedule-driven loads worth singling
      // out on most solar+battery homes -- the generator script's own
      // portable keyword rule, not a list of one house's circuits.
      const standout = eid.includes("pool") || eid.includes("hws");
      const color = nimbusFcHashColor(s.entity_id);
      const name = this._shortName(s);
      const h = this._history(s, name, color, "load", standout ? 3 : 1.5);
      if (h) series.push(h);
      const fcs = {
        entity: s.entity_id, name, extend_to: false, data_generator: NIMBUS_FC_GEN.value, color,
        stroke_width: standout ? 3 : 1.5, yaxis_id: "load",
        show: { in_header: false, in_legend: true, legend_value: true },
      };
      if (standout) {
        fcs.type = "area";
        fcs.opacity = 0.5;
      }
      series.push(fcs);
    }
    if (f.house) {
      const h = this._history(f.house, "Whole House Load", "#E0E0E0", "load", 1);
      if (h) series.push(h);
      series.push({
        entity: f.house.entity_id, name: "Whole House Load", extend_to: false,
        data_generator: NIMBUS_FC_GEN.value, color: "#E0E0E0", stroke_width: 3, yaxis_id: "load",
        show: { in_header: false, in_legend: true, legend_value: true },
      });
    }
    const cfg = this._base("Nimbus Load Forecasts", 500);
    cfg.yaxis = [
      { id: "power", show: false, min: -lmax, max: lmax },
      { id: "load", min: -lmax, max: lmax, decimals: 0, apex_config: { tickAmount: 6, title: { text: "kW" } } },
    ];
    cfg.series = series;
    return cfg;
  }

  _build(f) {
    const root = this.shadowRoot;
    root.innerHTML =
      "<style>:host{display:block;width:100%}.wrap{display:flex;flex-direction:column;gap:12px;width:100%}.wrap>*{display:block;width:100%}" +
      ".empty{padding:16px;color:var(--secondary-text-color);font-size:13px}</style><div class=\"wrap\"></div>";
    const wrap = root.querySelector(".wrap");
    this._charts = [];
    const configs = [];
    if (this._which !== "loads" && (f.signals.length || f.solver || f.weather.length)) {
      configs.push(this._signalsConfig(f));
    }
    if (this._which !== "signals" && (f.loads.length || f.house)) configs.push(this._loadsConfig(f));
    if (!configs.length) {
      wrap.innerHTML =
        '<ha-card><div class="empty">No Nimbus forecasts yet. Add a Load or Power Signal under ' +
        "Settings → Devices &amp; Services → Nimbus. Each appears here after its first training run.</div></ha-card>";
      return;
    }
    for (const cfg of configs) {
      const el = document.createElement("apexcharts-card");
      try {
        el.setConfig(cfg);
      } catch (err) {
        const msg = document.createElement("ha-card");
        msg.innerHTML =
          '<div class="empty">Nimbus Forecaster: ' + String(err && err.message ? err.message : err) + "</div>";
        wrap.appendChild(msg);
        continue;
      }
      wrap.appendChild(el);
      this._charts.push(el);
    }
  }

  _renderMissing() {
    this._signature = null;
    this._charts = [];
    this.shadowRoot.innerHTML =
      "<style>.empty{padding:16px;color:var(--secondary-text-color);font-size:13px}</style>" +
      '<ha-card><div class="empty"><b>Nimbus Forecaster needs ApexCharts Card.</b> Install ' +
      "<i>apexcharts-card</i> from HACS (Frontend), then refresh the browser.</div></ha-card>";
  }

  // The generated apexcharts-card configs, for tests and for anyone who
  // wants to copy the YAML into their own dashboard and edit it.
  buildConfigs() {
    const f = this._discover();
    return { signals: this._signalsConfig(f), loads: this._loadsConfig(f) };
  }
}

customElements.define("nimbus-forecast-card", NimbusForecastCard);

window.customCards = window.customCards || [];
window.customCards.push({
  type: "nimbus-forecast-card",
  name: "Nimbus Forecaster",
  description:
    "The Nimbus Power Signals and Load Forecasts charts, built automatically from this install's own Nimbus entities (needs ApexCharts Card).",
});
